371	export function useChatRequest() {
372	  const active = useRef<{ requestId: string; controller: AbortController } | null>(null);
373	  const [status, setStatus] = useState<"idle" | "running" | "completed" | "failed" | "canceled">("idle");
374	  const [error, setError] = useState("");
375	  const [conversationId, setConversationId] = useState<string | null>(null);
376	
377	  async function send(payload: { conversationId: string; message: string; context?: Record<string, unknown>; attachments?: ChatAttachment[] }, onEvent?: (event: ChatStreamEvent) => void) {
378	    if (active.current) return null;
379	    const run = { requestId: crypto.randomUUID(), controller: new AbortController() };
380	    active.current = run;
381	    setConversationId(payload.conversationId);
382	    setStatus("running");
383	    setError("");
384	    try {
385	      const response = await fetch("/api/chat", { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" },
386	        signal: run.controller.signal, body: JSON.stringify({ ...payload, requestId: run.requestId }) });
387	      // Events from a canceled run are never shown.
388	      const result = await readResponse(response, event => { if (active.current === run) onEvent?.(event); });
389	      if (active.current !== run) return null;
390	      if (!result.ok) throw new Error(result.body.error ?? "Could not answer");
391	      setStatus("completed");
392	      return result.body as ChatAnswer;
393	    } catch (cause) {
394	      if (active.current === run) { setStatus("failed"); setError(cause instanceof Error ? cause.message : "Could not answer"); }
395	      return null;
396	    } finally { if (active.current === run) active.current = null; }
397	  }
398	
399	  async function cancel() {
400	    const run = active.current;
401	    if (!run) return;
402	    try {
403	      let response: Response | undefined;
404	      // Cancellation can arrive before the server has claimed this request.
405	      for (let attempt = 0; attempt < 10; attempt++) {
406	        response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId: run.requestId }) });
407	        if (response.status !== 404) break;
408	        await new Promise(resolve => setTimeout(resolve, 100));
409	      }
410	      const result = await response!.json();
411	      if (!response!.ok) throw new Error(result.error ?? "Could not cancel; try again");
412	      if (result.status === "canceled" && active.current === run) {
413	        active.current = null;
414	        run.controller.abort();
415	        setStatus("canceled");
416	      }
417	    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not cancel; try again"); }
418	  }
419	
420	  /** The in-flight request, which steer messages target. */
421	  const requestId = () => active.current?.requestId ?? null;
422	  return { send, cancel, requestId, status, error, busy: status === "running", conversationId };
423	}
